using Microsoft.Extensions.Hosting;using Microsoft.Extensions.Options;using TradingSystem.Application.Locking;using TradingSystem.Application.Positions;using TradingSystem.Binance.Market.Contracts;using TradingSystem.Binance.Orders;using TradingSystem.Domain.Enums;
namespace StrategyService.Bots.Bot8011;public sealed class Bot8011TrailingWorker(IOptions<Bot8011Options> options, IPositionStore store, IBinanceFuturesMarketClient market, SafeBinanceOrderService safe, Bot8011Stop3OrderService stop3, Bot8011TrailingPriceCache cache, IPositionLockProvider locks):BackgroundService{readonly Bot8011Options o = options.Value;protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){foreach(var p in (await store.GetAllAsync(o.BotName, ct)).Where(x => !x.Closed && x.TpExecuted && x.Stop3Created && !x.Stop3Pending && !x.TrailingInProgress && x.Stop3Current.HasValue && x.RemainingQuantity>0)){var price = cache.TryGetFresh(TimeSpan.FromSeconds(o.TrailingPriceMaxAgeSeconds), out var x)?x:await market.GetMarkPriceAsync(p.Symbol, ct);var candidate = p.Side==PositionSide.Long && price>=p.Stop3Current.Value+o.Stop3TrailingStep?p.Stop3Current.Value+o.Stop3TrailingBuffer:p.Side==PositionSide.Short && price<=p.Stop3Current.Value-o.Stop3TrailingStep?p.Stop3Current.Value-o.Stop3TrailingBuffer:p.Stop3Current.Value;if(candidate==p.Stop3Current)continue;await Move(p.ShortId, candidate, ct);}await Task.Delay(TimeSpan.FromSeconds(o.TrailingFallbackIntervalSeconds), ct);}}async Task Move(string id, decimal candidate, CancellationToken ct){await using var l = await locks.TryAcquireAsync(o.BotName, id, TimeSpan.FromSeconds(30), ct);if(l is null)return;var p = await store.GetAsync(o.BotName, id, ct);if(p is null || p.Closed || string.IsNullOrWhiteSpace(p.Stop3OrderId))return;p.TrailingInProgress = true;p.Stop3NewPending = candidate;await store.SaveAsync(p, ct);if(!await safe.SafeCancelAlgoAsync(p.Symbol, p.Stop3OrderId, p.Stop3ClientId, ct)){p.TrailingInProgress = false;p.Stop3NewPending = null;await store.SaveAsync(p, ct);return;}try{var seq = p.TrailCount+1;var n = await stop3.CreateTrailingAsync(p, candidate, seq, ct);p.Stop3ClientId = n.ClientAlgoId;p.Stop3OrderId = n.AlgoOrderId;p.Stop3Current = n.TriggerPrice;p.Stop3Status = n.Status;p.Stop3NewPending = null;p.TrailingInProgress = false;p.TrailCount = seq;await store.SaveAsync(p, ct);}catch{p.TrailingInProgress = false;p.Stop3Created = false;p.Stop3Pending = true;p.ProtectiveActive = false;await store.SaveAsync(p, ct);throw;}}}
